import { pool } from '../config/database.js';
import { accountNotFound } from '../utils/AppError.js';
import { toAccount } from '../utils/serializers.js';

/** New accounts always start at balance 0; id and created_at are generated by the database. */
export async function createAccount({ name }) {
  const { rows } = await pool.query(
    'INSERT INTO accounts (name) VALUES ($1) RETURNING id, name, balance, created_at',
    [name]
  );
  return toAccount(rows[0]);
}

export async function getAccount(accountId) {
  const { rows } = await pool.query(
    'SELECT id, name, balance, created_at FROM accounts WHERE id = $1',
    [accountId]
  );
  if (rows.length === 0) throw accountNotFound(accountId);
  return toAccount(rows[0]);
}

export async function getBalance(accountId) {
  const account = await getAccount(accountId);
  return { account_id: account.id, balance: account.balance };
}

/** Throws 404 if the account does not exist. Accepts an optional client to run inside a DB transaction. */
export async function assertAccountExists(accountId, db = pool) {
  const { rowCount } = await db.query('SELECT 1 FROM accounts WHERE id = $1', [accountId]);
  if (rowCount === 0) throw accountNotFound(accountId);
}
